import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Executive Summary","description":"","frontmatter":{},"headers":[],"relativePath":"whitepaper/executive-summary.md","filePath":"whitepaper/executive-summary.md"}'),n={name:"whitepaper/executive-summary.md"};function r(o,t,d,l,p,h){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="executive-summary" tabindex="-1">Executive Summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive Summary&quot;">​</a></h1><p>The <strong>PAI Protocol (PPP)</strong> is a universal wire protocol for autonomous agent communication. It defines a self-contained, verifiable, and routable message format for agent-to-agent, agent-to-human, and human-to-agent communication.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Current agent communication suffers from:</p><ul><li><strong>Fragmentation</strong>: Every platform has proprietary protocols</li><li><strong>No Verifiability</strong>: No cryptographic proof of message integrity</li><li><strong>No Routing</strong>: Can&#39;t route messages across agent meshes</li><li><strong>No Audit Trail</strong>: No immutable record of agent communications</li><li><strong>Vendor Lock-in</strong>: Proprietary protocols create walled gardens</li></ul><h2 id="the-ppp-solution" tabindex="-1">The PPP Solution <a class="header-anchor" href="#the-ppp-solution" aria-label="Permalink to &quot;The PPP Solution&quot;">​</a></h2><p><strong>PPP (PAI Protocol)</strong> is a universal wire protocol designed for the agent economy:</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>Self-Contained</strong></td><td>Header + Body + Receipt in one document</td></tr><tr><td><strong>Verifiable</strong></td><td>Receipt = TrustChain proof + Sigstore anchoring</td></tr><tr><td><strong>Routable</strong></td><td>Endpoint URI in header enables mesh routing</td></tr><tr><td><strong>Versioned</strong></td><td>Explicit versioning with backward compatibility</td></tr><tr><td><strong>Transport Agnostic</strong></td><td>HTTP, WebSocket, QUIC, libp2p, email, etc.</td></tr></tbody></table><h2 id="core-architecture" tabindex="-1">Core Architecture <a class="header-anchor" href="#core-architecture" aria-label="Permalink to &quot;Core Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.ppp Document</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ Header                              │</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│ Body (JSON Schema validated)        │</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│ Receipt (TrustChain + Sigstore)     │</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><h3 id="header-fields" tabindex="-1">Header Fields <a class="header-anchor" href="#header-fields" aria-label="Permalink to &quot;Header Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>proto</code></td><td>string</td><td>Yes</td><td>Protocol version (<code>ppp/1.0</code>)</td></tr><tr><td><code>type</code></td><td>enum</td><td>Yes</td><td><code>request</code> | <code>response</code> | <code>event</code></td></tr><tr><td><code>endpoint</code></td><td>string</td><td>Yes</td><td>Target <code>.PAI</code> endpoint URI</td></tr><tr><td><code>id</code></td><td>uuid-v7</td><td>Yes</td><td>Unique message ID</td></tr><tr><td><code>from</code></td><td>did:agent</td><td>Yes</td><td>Sender DID</td></tr><tr><td><code>to</code></td><td>did:agent / *</td><td>Yes</td><td>Recipient DID</td></tr><tr><td><code>ts</code></td><td>ISO8601</td><td>Yes</td><td>Timestamp</td></tr><tr><td><code>ttl</code></td><td>int</td><td>No</td><td>Time-to-live (seconds)</td></tr><tr><td><code>trace</code></td><td>string</td><td>No</td><td>Distributed trace ID</td></tr></tbody></table><h3 id="body" tabindex="-1">Body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;Body&quot;">​</a></h3><p>Arbitrary JSON with required <code>type</code> field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;verify.kyc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pioneer.username&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="receipt-trustchain-proof" tabindex="-1">Receipt (TrustChain Proof) <a class="header-anchor" href="#receipt-trustchain-proof" aria-label="Permalink to &quot;Receipt (TrustChain Proof)&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:abc123...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;signature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MEUCIQD...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;signer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;did:agent:pi:agent1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;chain_hash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:abc123...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sequence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12345</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;anchored&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;anchor_tx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0xabc123...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="key-innovations" tabindex="-1">Key Innovations <a class="header-anchor" href="#key-innovations" aria-label="Permalink to &quot;Key Innovations&quot;">​</a></h2><h3 id="_1-trustchain-receipts" tabindex="-1">1. TrustChain Receipts <a class="header-anchor" href="#_1-trustchain-receipts" aria-label="Permalink to &quot;1. TrustChain Receipts&quot;">​</a></h3><p>Every message gets a cryptographic receipt anchored to:</p><ul><li><strong>TrustChain</strong> (local hash chain)</li><li><strong>Sigstore/Rekor</strong> (public transparency log)</li><li><strong>Pi Network</strong> (periodic blockchain anchoring)</li></ul><h3 id="_2-mesh-routing" tabindex="-1">2. Mesh Routing <a class="header-anchor" href="#_2-mesh-routing" aria-label="Permalink to &quot;2. Mesh Routing&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent A ──► Gateway ──► Mesh ──► Agent B</span></span>
<span class="line"><span>     │              │          │</span></span>
<span class="line"><span>     ▼              ▼          ▼</span></span>
<span class="line"><span>  .ppp msg      .ppp msg   .ppp msg</span></span></code></pre></div><h3 id="_3-transport-agnostic" tabindex="-1">3. Transport Agnostic <a class="header-anchor" href="#_3-transport-agnostic" aria-label="Permalink to &quot;3. Transport Agnostic&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/WebSocket  ──► PPP</span></span>
<span class="line"><span>libp2p/QUIC     ──► PPP</span></span>
<span class="line"><span>Email/SMTP      ──► PPP</span></span>
<span class="line"><span>Matrix/IRC      ──► PPP</span></span></code></pre></div><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain</th><th>Application</th></tr></thead><tbody><tr><td><strong>Agent Commerce</strong></td><td>ACP payments, escrow, invoicing</td></tr><tr><td><strong>Agent Discovery</strong></td><td>Capability broadcast, matchmaking</td></tr><tr><td><strong>Multi-Agent Systems</strong></td><td>Swarm coordination, task delegation</td></tr><tr><td><strong>Human-Agent</strong></td><td>Verified human↔agent communication</td></tr><tr><td><strong>Cross-Platform</strong></td><td>Bridge Discord, Matrix, Email, Matrix</td></tr></tbody></table><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Timeline</th><th>Deliverables</th></tr></thead><tbody><tr><td><strong>v1.0</strong></td><td>Q3 2026</td><td>Core spec, TypeScript/Rust SDKs, reference gateway</td></tr><tr><td><strong>v1.1</strong></td><td>Q4 2026</td><td>Mesh routing, ACP integration, ADP sync</td></tr><tr><td><strong>v2.0</strong></td><td>Q1 2027</td><td>Mesh networking, DHT routing, light clients</td></tr></tbody></table><h2 id="get-involved" tabindex="-1">Get Involved <a class="header-anchor" href="#get-involved" aria-label="Permalink to &quot;Get Involved&quot;">​</a></h2><ul><li><strong>Spec</strong>: <a href="https://github.com/pai-list/PAI-Protocol" target="_blank" rel="noreferrer">GitHub</a></li><li><strong>Discord</strong>: <a href="https://discord.gg/pai-universe" target="_blank" rel="noreferrer">PAI Universe</a></li><li><strong>Spec Repo</strong>: <code>pai-list/PAI-Protocol</code></li></ul><hr><p><em>PPP v1.0-draft — Built for the Agent Economy</em> EOF</p>`,33)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
